    """Keep explicit heating/mesh/error text; qualify M73 percentage messages."""
    import re
    value = re.sub(r'\s+TC\s+\d+(?:/\d+)?', '', message).strip()
    if state == "printing":
        if re.fullmatch(r"\d{1,3}%(?:\s+TC \d+(?:/\d+)?)?", value):
            return translate("PRINTING...") + " " + value
        if value == "PRINTING...":
            percent = max(0, min(100, int(progress * 100)))
            return translate(value) + f" {percent}%"
    return translate(value)


def _lugo_print_message(message, state, progress, translate):
    import re
    terminal = {'paused': 'Print paused', 'cancelled': 'Print cancelled',
                'cancelling': 'Print cancelled', 'complete': 'Print completed'}
    if state in terminal:
        return translate(terminal[state])
    value = re.sub(r'\s+TC\s+\d+(?:/\d+)?', '', message).strip()
    if state == 'printing' and (re.fullmatch(r'\d{1,3}%', value) or
                                value in ('PRINTING...', 'RESUME PRINTING...')):
        percent = max(0, min(100, int(progress * 100)))
        if value.endswith('%'):
            percent = max(0, min(100, int(value[:-1])))
        return translate('PRINTING...') + f' {percent}%'
    return translate(value)
